27	import org.springframework.http.HttpHeaders;
28	import org.springframework.http.HttpStatus;
29	import org.springframework.http.ResponseEntity;
30	import org.springframework.samples.petclinic.rest.advice.DuplicateOwnerHouseholdException;
31	import org.springframework.samples.petclinic.rest.advice.DuplicateOwnerTelephoneException;
32	import org.springframework.samples.petclinic.rest.advice.InvalidFieldsException;
33	import org.springframework.samples.petclinic.rest.advice.RequiredFieldsMissingException;
34	import org.springframework.samples.petclinic.mapper.OwnerMapper;
35	import org.springframework.samples.petclinic.mapper.PetMapper;
36	import org.springframework.samples.petclinic.mapper.VisitMapper;
37	import org.springframework.samples.petclinic.model.Owner;
38	import org.springframework.samples.petclinic.model.Pet;
39	import org.springframework.samples.petclinic.model.Visit;
40	import org.springframework.samples.petclinic.rest.api.OwnersApi;
41	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
42	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
43	import org.springframework.samples.petclinic.rest.dto.PetDto;
44	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
45	import org.springframework.samples.petclinic.rest.dto.VisitDto;
46	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
47	import org.springframework.samples.petclinic.service.ClinicService;
48	import org.springframework.security.access.prepost.PreAuthorize;
49	import org.springframework.util.StringUtils;
50	import org.springframework.web.bind.annotation.CrossOrigin;
51	import org.springframework.web.bind.annotation.RequestMapping;
52	import org.springframework.web.bind.annotation.RestController;
53	import org.springframework.web.util.UriComponentsBuilder;
54	
55	import jakarta.transaction.Transactional;
56	
57	/**
58	 * @author Vitaliy Fedoriv
59	 */
60	
61	@RestController
62	@CrossOrigin(exposedHeaders = "errors, content-type")
63	@RequestMapping("/api")
64	public class OwnerRestControllerV1 implements OwnersApi {
65	
66	    /**
67	     * Syntactic email check: a non-empty local part, an {@code @}, and a dotted domain, with no
68	     * whitespace or additional {@code @} characters. Deliberately permissive - it enforces basic
69	     * address shape rather than full RFC 5322 conformance.
70	     */
71	    private static final Pattern EMAIL_PATTERN =
72	        Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
73	
74	    /**
75	     * Common street-type abbreviations expanded during address normalization. Keys and values are
76	     * upper-cased so the mapping is applied after the address has been upper-cased.
77	     */
78	    private static final Map<String, String> ADDRESS_ABBREVIATIONS = Map.of(
79	        "ST", "STREET",
80	        "RD", "ROAD",
81	        "AVE", "AVENUE");
82	
83	    private final ClinicService clinicService;
84	
85	    private final OwnerMapper ownerMapper;
86	
87	    private final PetMapper petMapper;
88	
89	    private final VisitMapper visitMapper;
90	
91	    public OwnerRestControllerV1(ClinicService clinicService,
92	                                 OwnerMapper ownerMapper,
93	                                 PetMapper petMapper,
94	                                 VisitMapper visitMapper) {
95	        this.clinicService = clinicService;
96	        this.ownerMapper = ownerMapper;
97	        this.petMapper = petMapper;
98	        this.visitMapper = visitMapper;
99	    }
100	
101	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
102	    @Override
103	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
104	        Collection<Owner> owners;
105	        if (lastName != null) {
106	            owners = this.clinicService.findOwnerByLastName(lastName);
107	        } else {
108	            owners = this.clinicService.findAllOwners();
109	        }
110	        if (owners.isEmpty()) {
111	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
112	        }
113	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
114	    }
115	
116	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
117	    @Override
118	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
119	        Owner owner = this.clinicService.findOwnerById(ownerId);
120	        if (owner == null) {
121	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
122	        }
123	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
124	    }
125	
126	    /**
127	     * Normalizes an owner's address: trims and collapses runs of whitespace to single spaces,
128	     * upper-cases the value, and expands common street-type abbreviations word-by-word
129	     * ({@code ST->STREET}, {@code RD->ROAD}, {@code AVE->AVENUE}). A {@code null} or blank value
130	     * normalizes to the empty string. The normalized value is what the application stores, returns
131	     * and compares for household detection.
132	     *
133	     * @param address the raw address value from the request, may be {@code null}
134	     * @return the normalized address, or the empty string when none was supplied
135	     */
136	    private String normalizeAddress(String address) {
137	        if (address == null) {
138	            return "";
139	        }
140	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
141	        if (collapsed.isEmpty()) {
142	            return "";
143	        }
144	        String[] tokens = collapsed.split(" ");
145	        StringBuilder normalized = new StringBuilder();
146	        for (int i = 0; i < tokens.length; i++) {
147	            if (i > 0) {
148	                normalized.append(' ');
149	            }
150	            normalized.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
151	        }
152	        return normalized.toString();
153	    }
154	
155	    /**
156	     * Rejects an owner payload that is missing or blank in any required field. The response body's
157	     * {@code errors} array lists the name of each offending field.
158	     *
159	     * @param ownerFieldsDto the owner payload to validate
160	     * @throws RequiredFieldsMissingException if one or more required fields are missing or blank
161	     */
162	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
163	        List<String> missingFields = new ArrayList<>();
164	        if (!StringUtils.hasText(ownerFieldsDto.getFirstName())) {
165	            missingFields.add("firstName");
166	        }
167	        if (!StringUtils.hasText(ownerFieldsDto.getLastName())) {
168	            missingFields.add("lastName");
169	        }
170	        if (!StringUtils.hasText(ownerFieldsDto.getAddress())) {
171	            missingFields.add("address");
172	        }
173	        if (!StringUtils.hasText(ownerFieldsDto.getCity())) {
174	            missingFields.add("city");
175	        }
176	        if (!StringUtils.hasText(ownerFieldsDto.getTelephone())) {
177	            missingFields.add("telephone");
178	        }
179	        if (!missingFields.isEmpty()) {
180	            throw new RequiredFieldsMissingException(missingFields);
181	        }
182	    }
183	
184	    /**
185	     * Normalizes a telephone number into E.164 form. Spaces, dashes and brackets are stripped. A
186	     * leading '+' and its country code are kept as given; otherwise country code '+61' is assumed
187	     * and a single leading '0' is dropped from the national digits. The result must be a '+'
188	     * followed by 8 to 15 digits.
189	     *
190	     * @param telephone the raw telephone value from the request
191	     * @return the E.164 telephone (e.g. {@code +61412345678})
192	     * @throws InvalidFieldsException if the value cannot form a valid E.164 number
193	     */
194	    private String normalizeTelephone(String telephone) {
195	        if (telephone == null) {
196	            throw new InvalidFieldsException(List.of("telephone"));
197	        }
198	        String trimmed = telephone.trim();
199	        boolean international = trimmed.startsWith("+");
200	        String cleaned = trimmed.replaceAll("[\\s\\-()]", "");
201	        String digits;
202	        if (international) {
203	            digits = cleaned.substring(1);
204	        } else {
205	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
206	            digits = "61" + national;
207	        }
208	        if (!digits.matches("[0-9]{8,15}")) {
209	            throw new InvalidFieldsException(List.of("telephone"));
210	        }
211	        return "+" + digits;
212	    }
213	
214	    /**
215	     * Best-effort normalization of an existing owner's stored telephone into E.164 form for
216	     * duplicate comparison, returning {@code null} when the value cannot form valid E.164.
217	     *
218	     * @param telephone an existing stored telephone value, may be {@code null}
219	     * @return the E.164 form, or {@code null} when it cannot be normalized
220	     */
221	    private String toE164OrNull(String telephone) {
222	        if (telephone == null) {
223	            return null;
224	        }
225	        try {
226	            return normalizeTelephone(telephone);
227	        }
228	        catch (InvalidFieldsException ex) {
229	            return null;
230	        }
231	    }
232	
233	    /**
234	     * Normalizes an optional email address. Email is not required, so a missing or blank value is
235	     * accepted and yields {@code null} (no email stored). When a non-blank value is supplied it must
236	     * be a syntactically valid address; the accepted value is returned lower-cased.
237	     *
238	     * @param email the raw email value from the request, may be {@code null}
239	     * @return the lower-cased email, or {@code null} when none was supplied
240	     * @throws InvalidFieldsException if a non-blank value is not a syntactically valid address
241	     */
242	    private String normalizeEmail(String email) {
243	        if (email == null || email.isBlank()) {
244	            return null;
245	        }
246	        String trimmed = email.trim();
247	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
248	            throw new InvalidFieldsException(List.of("email"));
249	        }
250	        return trimmed.toLowerCase(Locale.ROOT);
251	    }
252	
253	    /**
254	     * Rejects a telephone that, once normalized, is already used by any existing owner. Existing
255	     * owners' telephones are normalized the same way before comparison so differently-formatted
256	     * values representing the same number are treated as duplicates.
257	     *
258	     * @param telephone the normalized (E.164) telephone of the owner being created
259	     * @throws DuplicateOwnerTelephoneException if another owner already uses the telephone
260	     */
261	    private void requireUniqueTelephone(String telephone) {
262	        boolean taken = this.clinicService.findAllOwners().stream()
263	            .map(Owner::getTelephone)
264	            .map(this::toE164OrNull)
265	            .filter(existing -> existing != null)
266	            .anyMatch(telephone::equals);
267	        if (taken) {
268	            throw new DuplicateOwnerTelephoneException(telephone);
269	        }
270	    }
271	
272	    /**
273	     * Collapses surrounding and internal whitespace and lower-cases a value so that owner household
274	     * fields (last name, address) can be compared case-insensitively with collapsed whitespace. A
275	     * {@code null} value normalizes to the empty string.
276	     *
277	     * @param value the raw field value, may be {@code null}
278	     * @return the trimmed, whitespace-collapsed, lower-cased form
279	     */
280	    private String normalizeHousehold(String value) {
281	        if (value == null) {
282	            return "";
283	        }
284	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
285	    }
286	
287	    /**
288	     * Rejects an owner whose last name and address already match another owner (compared
289	     * case-insensitively with collapsed whitespace) - i.e. they would share a household - unless the
290	     * request opts in via {@code sharesHousehold}. Existing owners' fields are normalized the same
291	     * way before comparison.
292	     *
293	     * @param lastName the last name of the owner being created
294	     * @param address the address of the owner being created
295	     * @throws DuplicateOwnerHouseholdException if another owner shares the household
296	     */
297	    private void requireUniqueHousehold(String lastName, String address) {
298	        String normalizedLastName = normalizeHousehold(lastName);
299	        String normalizedAddress = normalizeHousehold(address);
300	        boolean shared = this.clinicService.findAllOwners().stream()
301	            .anyMatch(existing -> normalizeHousehold(existing.getLastName()).equals(normalizedLastName)
302	                && normalizeHousehold(existing.getAddress()).equals(normalizedAddress));
303	        if (shared) {
304	            throw new DuplicateOwnerHouseholdException(lastName, address);
305	        }
306	    }
307	
308	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
309	    @Override
310	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
311	        ownerFieldsDto.setAddress(normalizeAddress(ownerFieldsDto.getAddress()));
312	        validateRequiredFields(ownerFieldsDto);
313	        String telephone = normalizeTelephone(ownerFieldsDto.getTelephone());
314	        requireUniqueTelephone(telephone);
315	        if (!Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
316	            requireUniqueHousehold(ownerFieldsDto.getLastName(), ownerFieldsDto.getAddress());
317	        }
318	        String email = normalizeEmail(ownerFieldsDto.getEmail());
319	        HttpHeaders headers = new HttpHeaders();
320	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
321	        owner.setTelephone(telephone);
322	        owner.setEmail(email);
323	        if (owner.getRegistrationDate() == null) {
324	            owner.setRegistrationDate(LocalDate.now());
325	        }
326	        this.clinicService.saveOwner(owner);
327	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
328	        headers.setLocation(UriComponentsBuilder.newInstance()
329	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
330	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
331	    }
332	
333	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
334	    @Override
335	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
336	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
337	        if (currentOwner == null) {
338	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
339	        }
340	        currentOwner.setAddress(ownerFieldsDto.getAddress());
341	        currentOwner.setCity(ownerFieldsDto.getCity());
342	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
343	        currentOwner.setLastName(ownerFieldsDto.getLastName());
344	        currentOwner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
345	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
346	        this.clinicService.saveOwner(currentOwner);
347	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
348	    }
349	
350	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
351	    @Transactional
352	    @Override
353	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
354	        Owner owner = this.clinicService.findOwnerById(ownerId);
355	        if (owner == null) {
356	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
357	        }
358	        this.clinicService.deleteOwner(owner);
359	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
360	    }
361	
362	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
363	    @Override
364	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
365	        Owner owner = this.clinicService.findOwnerById(ownerId);
366	        if (owner == null) {
367	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
368	        }
369	        HttpHeaders headers = new HttpHeaders();
370	        Pet pet = petMapper.toPet(petFieldsDto);
371	        owner.setId(ownerId);
372	        pet.setOwner(owner);
373	        pet.getType().setName(null);
374	        this.clinicService.savePet(pet);
375	        PetDto petDto = petMapper.toPetDto(pet);
376	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
377	            .buildAndExpand(pet.getId()).toUri());
378	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
379	    }
380	
381	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
382	    @Override
383	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
384	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
385	        if (currentOwner != null) {
386	            Pet currentPet = this.clinicService.findPetById(petId);
387	            if (currentPet != null) {
388	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
389	                currentPet.setName(petFieldsDto.getName());
390	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
391	                this.clinicService.savePet(currentPet);
392	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
393	            }
394	        }
395	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
396	    }
397	
398	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
399	    @Override
400	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
401	        HttpHeaders headers = new HttpHeaders();
402	        Visit visit = visitMapper.toVisit(visitFieldsDto);
403	        Pet pet = new Pet();
404	        pet.setId(petId);
405	        visit.setPet(pet);
406	        this.clinicService.saveVisit(visit);
407	        VisitDto visitDto = visitMapper.toVisitDto(visit);
408	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
409	            .buildAndExpand(visit.getId()).toUri());
410	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
411	    }
412	
413	
414	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
415	    @Override
416	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
417	        Owner owner = this.clinicService.findOwnerById(ownerId);
418	        if (owner != null) {
419	            Pet pet = owner.getPet(petId);
420	            if (pet != null) {
421	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
422	            }
423	        }
424	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
425	    }
426	}
