17	package org.springframework.samples.petclinic.rest.advice;
18	
19	import java.net.URI;
20	import java.time.Instant;
21	import java.util.List;
22	import java.util.Objects;
23	
24	import jakarta.servlet.http.HttpServletRequest;
25	import org.slf4j.Logger;
26	import org.slf4j.LoggerFactory;
27	import org.springframework.dao.DataIntegrityViolationException;
28	import org.springframework.http.HttpStatus;
29	import org.springframework.http.ProblemDetail;
30	import org.springframework.http.ResponseEntity;
31	import org.springframework.samples.petclinic.rest.controller.BindingErrorsResponse;
32	import org.springframework.samples.petclinic.rest.dto.ValidationMessageDto;
33	import org.springframework.security.access.AccessDeniedException;
34	import org.springframework.validation.BindingResult;
35	import org.springframework.validation.FieldError;
36	import org.springframework.web.bind.MethodArgumentNotValidException;
37	import org.springframework.web.bind.annotation.ControllerAdvice;
38	import org.springframework.web.bind.annotation.ExceptionHandler;
39	import org.springframework.web.bind.annotation.ResponseBody;
40	
41	/**
42	 * Global Exception handler for REST controllers.
43	 * <p>
44	 * This class handles exceptions thrown by REST controllers and returns appropriate HTTP responses to the client.
45	 *
46	 * @author Vitaliy Fedoriv
47	 * @author Alexander Dudkin
48	 */
49	@ControllerAdvice
50	public class ExceptionControllerAdvice {
51	
52	    private static final Logger logger = LoggerFactory.getLogger(ExceptionControllerAdvice.class);
53	    private static final String ERROR_UNEXPECTED = "An unexpected error occurred while processing your request";
54	    private static final String ERROR_DATA_INTEGRITY = "The requested resource could not be processed due to a data constraint violation";
55	    private static final String ERROR_INVALID_REQUEST = "The request contains invalid or missing parameters";
56	    private static final String ERROR_DUPLICATE_TELEPHONE = "An owner with the given telephone already exists";
57	    private static final String ERROR_DUPLICATE_HOUSEHOLD = "An owner with the given last name and address already exists";
58	
59	    /**
60	     * Private method for constructing the {@link ProblemDetail} object passing the name and details of the exception
61	     * class.
62	     *
63	     * @param e     Object referring to the thrown exception.
64	     * @param status HTTP response status.
65	     * @param url URL request.
66	     */
67	    private ProblemDetail detailBuild(Exception e, HttpStatus status, StringBuffer url, String detail) {
68	        ProblemDetail problemDetail = ProblemDetail.forStatus(status);
69	        problemDetail.setType(URI.create(url.toString()));
70	        problemDetail.setTitle(e.getClass().getSimpleName());
71	        problemDetail.setDetail(detail);
72	        problemDetail.setProperty("timestamp", Instant.now());
73	        problemDetail.setProperty("schemaValidationErrors", List.<ValidationMessageDto>of());
74	        return problemDetail;
75	    }
76	
77	    /**
78	     * Re-throws {@link AccessDeniedException} so Spring Security's {@code ExceptionTranslationFilter}
79	     * translates it as it normally would - 403 for an authenticated user lacking the required role,
80	     * or the configured entry point for an anonymous one. Without this, {@link #handleGeneralException}
81	     * would catch it and report an authorization failure as a 500.
82	     *
83	     * @param e The {@link AccessDeniedException} to propagate
84	     * @throws AccessDeniedException always
85	     */
86	    @ExceptionHandler(AccessDeniedException.class)
87	    public void handleAccessDeniedException(AccessDeniedException e) throws AccessDeniedException {
88	        throw e;
89	    }
90	
91	    /**
92	     * Handles all general exceptions by returning a 500 Internal Server Error status with error details.
93	     *
94	     * @param e The {@link Exception} to be handled
95	     * @param request {@link HttpServletRequest} object referring to the current request.
96	     * @return A {@link ResponseEntity} containing the error information and a 500 Internal Server Error status
97	     */
98	    @ExceptionHandler(Exception.class)
99	    @ResponseBody
100	    public ResponseEntity<ProblemDetail> handleGeneralException(Exception e, HttpServletRequest request) {
101	        logger.error("Unexpected error at {} {}", request.getMethod(), request.getRequestURI(), e);
102	        HttpStatus status = HttpStatus.INTERNAL_SERVER_ERROR;
103	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_UNEXPECTED);
104	        return ResponseEntity.status(status).body(detail);
105	    }
106	
107	    /**
108	     * Handles {@link DataIntegrityViolationException} which typically indicates database constraint violations. This
109	     * method returns a 404 Not Found status if an entity does not exist.
110	     *
111	     * @param e The {@link DataIntegrityViolationException} to be handled
112	     * @param request {@link HttpServletRequest} object referring to the current request.
113	     * @return A {@link ResponseEntity} containing the error information and a 404 Not Found status
114	     */
115	    @ExceptionHandler(DataIntegrityViolationException.class)
116	    @ResponseBody
117	    public ResponseEntity<ProblemDetail> handleDataIntegrityViolationException(DataIntegrityViolationException e, HttpServletRequest request) {
118	        logger.warn("Data integrity violation at {} {}: {}",
119	            request.getMethod(),
120	            request.getRequestURI(),
121	            e.getMessage());
122	        logger.debug("Data integrity violation stacktrace", e);
123	        HttpStatus status = HttpStatus.NOT_FOUND;
124	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_DATA_INTEGRITY);
125	        return ResponseEntity.status(status).body(detail);
126	    }
127	
128	    /**
129	     * Handles exception thrown by Bean Validation on controller methods parameters
130	     *
131	     * @param e The {@link MethodArgumentNotValidException} to be handled
132	     * @param request {@link HttpServletRequest} object referring to the current request.
133	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
134	     */
135	    @ExceptionHandler(MethodArgumentNotValidException.class)
136	    @ResponseBody
137	    public ResponseEntity<ProblemDetail> handleMethodArgumentNotValidException(MethodArgumentNotValidException e, HttpServletRequest request) {
138	        HttpStatus status = HttpStatus.BAD_REQUEST;
139	        BindingErrorsResponse errors = new BindingErrorsResponse();
140	        BindingResult bindingResult = e.getBindingResult();
141	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
142	        if (bindingResult.hasErrors()) {
143	            errors.addAllErrors(bindingResult);
144	            List<String> invalidFields = bindingResult.getFieldErrors().stream()
145	                .map(FieldError::getField)
146	                .distinct()
147	                .toList();
148	            detail.setProperty("errors", invalidFields);
149	            List<ValidationMessageDto> schemaValidationErrors = bindingResult.getFieldErrors().stream()
150	                .map(fieldError -> {
151	                    String rejectedValue = Objects.toString(fieldError.getRejectedValue(), "null");
152	                    String defaultMessage = Objects.toString(fieldError.getDefaultMessage(), "Validation failed");
153	                    String message = "Field '%s' %s (rejected value: %s)".formatted(
154	                        fieldError.getField(),
155	                        defaultMessage,
156	                        rejectedValue);
157	                    return new ValidationMessageDto(message)
158	                        .putAdditionalProperty("field", fieldError.getField())
159	                        .putAdditionalProperty("rejectedValue", rejectedValue)
160	                        .putAdditionalProperty("defaultMessage", defaultMessage);
161	                })
162	                .toList();
163	            logger.debug("Validation error at {} {}: {}",
164	                request.getMethod(),
165	                request.getRequestURI(),
166	                bindingResult.getFieldErrors());
167	            detail.setProperty("schemaValidationErrors", schemaValidationErrors);
168	            return ResponseEntity.status(status).body(detail);
169	        }
170	        return ResponseEntity.status(status).body(detail);
171	    }
172	
173	    /**
174	     * Handles {@link RequiredFieldsMissingException} raised when a request is missing or blank in
175	     * one or more required fields. Returns a 400 Bad Request whose body's {@code errors} array
176	     * lists the name of each offending field.
177	     *
178	     * @param e The {@link RequiredFieldsMissingException} to be handled
179	     * @param request {@link HttpServletRequest} object referring to the current request.
180	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
181	     */
182	    @ExceptionHandler(RequiredFieldsMissingException.class)
183	    @ResponseBody
184	    public ResponseEntity<ProblemDetail> handleRequiredFieldsMissingException(RequiredFieldsMissingException e, HttpServletRequest request) {
185	        HttpStatus status = HttpStatus.BAD_REQUEST;
186	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
187	        detail.setProperty("errors", e.getMissingFields());
188	        logger.debug("Missing required fields at {} {}: {}",
189	            request.getMethod(),
190	            request.getRequestURI(),
191	            e.getMissingFields());
192	        return ResponseEntity.status(status).body(detail);
193	    }
194	
195	    /**
196	     * Handles {@link InvalidFieldsException} raised when a request carries one or more fields
197	     * whose values are present but invalid. Returns a 400 Bad Request whose body's {@code errors}
198	     * array lists the name of each offending field.
199	     *
200	     * @param e The {@link InvalidFieldsException} to be handled
201	     * @param request {@link HttpServletRequest} object referring to the current request.
202	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
203	     */
204	    @ExceptionHandler(InvalidFieldsException.class)
205	    @ResponseBody
206	    public ResponseEntity<ProblemDetail> handleInvalidFieldsException(InvalidFieldsException e, HttpServletRequest request) {
207	        HttpStatus status = HttpStatus.BAD_REQUEST;
208	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
209	        detail.setProperty("errors", e.getInvalidFields());
210	        logger.debug("Invalid fields at {} {}: {}",
211	            request.getMethod(),
212	            request.getRequestURI(),
213	            e.getInvalidFields());
214	        return ResponseEntity.status(status).body(detail);
215	    }
216	
217	    /**
218	     * Handles {@link DuplicateOwnerTelephoneException} raised when an owner is created with a
219	     * normalized telephone that is already used by another owner. Returns a 409 Conflict whose
220	     * body's {@code errors} array names the offending {@code telephone} field.
221	     *
222	     * @param e The {@link DuplicateOwnerTelephoneException} to be handled
223	     * @param request {@link HttpServletRequest} object referring to the current request.
224	     * @return A {@link ResponseEntity} containing the error information and a 409 Conflict status.
225	     */
226	    @ExceptionHandler(DuplicateOwnerTelephoneException.class)
227	    @ResponseBody
228	    public ResponseEntity<ProblemDetail> handleDuplicateOwnerTelephoneException(DuplicateOwnerTelephoneException e, HttpServletRequest request) {
229	        HttpStatus status = HttpStatus.CONFLICT;
230	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_DUPLICATE_TELEPHONE);
231	        detail.setProperty("errors", List.of("telephone"));
232	        logger.debug("Duplicate owner telephone at {} {}: {}",
233	            request.getMethod(),
234	            request.getRequestURI(),
235	            e.getTelephone());
236	        return ResponseEntity.status(status).body(detail);
237	    }
238	
239	    /**
240	     * Handles {@link DuplicateOwnerHouseholdException} raised when an owner is created whose last
241	     * name and address already match another owner (a shared household) without the request opting
242	     * in via the {@code sharesHousehold} flag. Returns a 409 Conflict whose body's {@code errors}
243	     * array names the offending {@code lastName} and {@code address} fields.
244	     *
245	     * @param e The {@link DuplicateOwnerHouseholdException} to be handled
246	     * @param request {@link HttpServletRequest} object referring to the current request.
247	     * @return A {@link ResponseEntity} containing the error information and a 409 Conflict status.
248	     */
249	    @ExceptionHandler(DuplicateOwnerHouseholdException.class)
250	    @ResponseBody
251	    public ResponseEntity<ProblemDetail> handleDuplicateOwnerHouseholdException(DuplicateOwnerHouseholdException e, HttpServletRequest request) {
252	        HttpStatus status = HttpStatus.CONFLICT;
253	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_DUPLICATE_HOUSEHOLD);
254	        detail.setProperty("errors", List.of("lastName", "address"));
255	        logger.debug("Duplicate owner household at {} {}: lastName={} address={}",
256	            request.getMethod(),
257	            request.getRequestURI(),
258	            e.getLastName(),
259	            e.getAddress());
260	        return ResponseEntity.status(status).body(detail);
261	    }
262	
263	}
