        detail.setProperty("errors", e.getMissingFields());
        logger.debug("Missing required fields at {} {}: {}",
            request.getMethod(),
            request.getRequestURI(),
            e.getMissingFields());
        return ResponseEntity.status(status).body(detail);
    }

    /**
